ALTER TABLE public.paineis ADD COLUMN tipo_painel text NOT NULL DEFAULT 'individual', ADD COLUMN setor text NOT NULL DEFAULT '', ADD COLUMN responsavel text NOT NULL DEFAULT '';
ALTER TABLE public.paineis ADD CONSTRAINT painel_tipo_valid CHECK(tipo_painel IN ('individual','setor'));
ALTER TABLE public.documentos ADD COLUMN setor_id uuid;
CREATE TABLE public.documento_destinatarios(documento_id uuid NOT NULL REFERENCES public.documentos(id) ON DELETE CASCADE,user_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(documento_id,user_id));
GRANT SELECT ON public.documento_destinatarios TO authenticated; GRANT ALL ON public.documento_destinatarios TO service_role;
ALTER TABLE public.documento_destinatarios ENABLE ROW LEVEL SECURITY;
CREATE POLICY destinatarios_read ON public.documento_destinatarios FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.assinante_identidades(solicitacao_id uuid PRIMARY KEY REFERENCES public.solicitacoes_assinatura(id) ON DELETE CASCADE,nome text NOT NULL,funcao text NOT NULL,cpf text NOT NULL);
GRANT ALL ON public.assinante_identidades TO service_role; ALTER TABLE public.assinante_identidades ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.solicitacoes_internas(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),criado_por uuid NOT NULL DEFAULT auth.uid(),destinatario_id uuid NOT NULL,destinatario text NOT NULL,texto text NOT NULL,assinante_nome text NOT NULL,assinante_funcao text NOT NULL,assinado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.solicitacoes_internas TO authenticated; GRANT ALL ON public.solicitacoes_internas TO service_role; ALTER TABLE public.solicitacoes_internas ENABLE ROW LEVEL SECURITY;
CREATE POLICY solicitacoes_read ON public.solicitacoes_internas FOR SELECT TO authenticated USING(public.conta_ativa(auth.uid()) AND (criado_por=auth.uid() OR destinatario_id=auth.uid()));
CREATE TABLE public.documento_avisos(documento_id uuid NOT NULL REFERENCES public.documentos(id) ON DELETE CASCADE,user_id uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(documento_id,user_id));
GRANT SELECT,INSERT,DELETE ON public.documento_avisos TO authenticated; GRANT ALL ON public.documento_avisos TO service_role; ALTER TABLE public.documento_avisos ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.e_setor(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.paineis WHERE user_id=_uid AND tipo_painel='setor') $$;
REVOKE ALL ON FUNCTION public.e_setor(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.e_setor(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.acesso_documento(_id uuid,_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.conta_ativa(_uid) AND EXISTS(SELECT 1 FROM public.documentos d WHERE d.id=_id AND (public.has_role(_uid,'admin') OR d.criado_por=_uid OR EXISTS(SELECT 1 FROM public.documento_destinatarios x WHERE x.documento_id=d.id AND x.user_id=_uid) OR EXISTS(SELECT 1 FROM public.solicitacoes_assinatura s WHERE s.documento_id=d.id AND s.versao=d.versao AND (s.gestora='user:'||_uid::text OR EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=_uid AND r.role::text=s.gestora))) OR (d.setor_id IS NULL AND NOT public.e_setor(_uid) AND (public.pode_emitir(_uid) OR d.status='assinado' OR (d.processo_id IS NOT NULL AND public.acesso_processo(d.processo_id,_uid)))))) $$;
REVOKE ALL ON FUNCTION public.acesso_documento(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.acesso_documento(uuid,uuid) TO authenticated,service_role;
CREATE POLICY documentos_setor_isolado ON public.documentos AS RESTRICTIVE FOR SELECT TO authenticated USING(public.acesso_documento(id,auth.uid()));
CREATE POLICY documentos_recebidos ON public.documentos FOR SELECT TO authenticated USING(public.acesso_documento(id,auth.uid()));
CREATE OR REPLACE FUNCTION public.documento_existe(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.acesso_documento(_id,auth.uid()) $$;
CREATE POLICY aviso_read ON public.documento_avisos FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.acesso_documento(documento_id,auth.uid()));
CREATE POLICY aviso_insert ON public.documento_avisos FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.acesso_documento(documento_id,auth.uid()));
CREATE POLICY aviso_delete ON public.documento_avisos FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.proximo_numero_documento(_tipo text,_ano integer) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(max(numero),0)+1 FROM public.documentos WHERE upper(tipo)=upper(_tipo) AND ano=_ano AND setor_id IS NOT DISTINCT FROM CASE WHEN public.e_setor(auth.uid()) THEN auth.uid() ELSE NULL::uuid END AND public.pode_emitir(auth.uid()) $$;
REVOKE ALL ON FUNCTION public.proximo_numero_documento(text,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.proximo_numero_documento(text,integer) TO authenticated;
DO $$ DECLARE f text; BEGIN
SELECT pg_get_functiondef('public.salvar_documento(uuid,jsonb,uuid)'::regprocedure) INTO f;
f:=replace(f,'AND id IS DISTINCT FROM _id','AND setor_id IS NOT DISTINCT FROM (CASE WHEN _id IS NOT NULL THEN (SELECT setor_id FROM public.documentos WHERE id=_id) WHEN public.e_setor(auth.uid()) THEN auth.uid() ELSE NULL::uuid END) AND id IS DISTINCT FROM _id');
f:=replace(f,'criado_por,processo_id) VALUES','criado_por,processo_id,setor_id) VALUES');
f:=replace(f,'auth.uid(),_processo) RETURNING','auth.uid(),_processo,CASE WHEN public.e_setor(auth.uid()) THEN auth.uid() ELSE NULL::uuid END) RETURNING'); EXECUTE f;
SELECT pg_get_functiondef('public.encaminhar_documento(uuid,jsonb,text,date,text)'::regprocedure) INTO f;
f:=replace(f,'IF NOT public.has_role(auth.uid(),''admin'') OR NOT public.conta_ativa(auth.uid())','IF NOT (public.has_role(auth.uid(),''admin'') OR (public.e_setor(auth.uid()) AND public.pode_emitir(auth.uid()))) OR NOT public.conta_ativa(auth.uid())');
f:=replace(f,'IF d.id IS NULL OR jsonb_array_length','IF d.id IS NULL OR (NOT public.has_role(auth.uid(),''admin'') AND d.criado_por IS DISTINCT FROM auth.uid()) OR jsonb_array_length'); EXECUTE f; END $$;
CREATE OR REPLACE FUNCTION public.excluir_documento(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.documentos; BEGIN SELECT * INTO d FROM public.documentos WHERE id=_id FOR UPDATE;
IF d.id IS NULL OR NOT public.conta_ativa(auth.uid()) OR NOT(public.has_role(auth.uid(),'admin') OR (public.pode_emitir(auth.uid()) AND d.criado_por=auth.uid() AND d.status='desenvolvendo' AND NOT d.analise_admin AND d.emitido_em IS NULL)) THEN RAISE EXCEPTION 'Exclusão não autorizada'; END IF;
IF EXISTS(SELECT 1 FROM public.processos WHERE oficio_id=_id) THEN RAISE EXCEPTION 'Documento utilizado na abertura de um processo'; END IF;
DELETE FROM public.documento_versoes WHERE documento_id=_id; DELETE FROM public.documentos WHERE id=_id; END $$;
REVOKE ALL ON FUNCTION public.excluir_documento(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.excluir_documento(uuid) TO authenticated;
NOTIFY pgrst,'reload schema';